258:                 self.viewport.top_line = self.cursor.line.saturating_sub(padding);
259:             } else if self.cursor.line > bottom_boundary {
260:                 let desired_top = self.cursor.line + padding + 1;
261:                 self.viewport.top_line = desired_top.saturating_sub(self.viewport.visible_lines);
262:             }
263: 
264:             // Clamp to valid range
265:             let max_top = total_lines.saturating_sub(self.viewport.visible_lines);
266:             self.viewport.top_line = self.viewport.top_line.min(max_top);
267:         } else {
268:             self.viewport.top_line = 0;
269:         }
270: 
271:         // Horizontal scrolling (always check, independent of vertical)
272:         const HORIZONTAL_MARGIN: usize = 4;
273:         let left_safe = self.viewport.left_column + HORIZONTAL_MARGIN;
274:         let right_safe = self.viewport.left_column + self.viewport.visible_columns - HORIZONTAL_MARGIN;
275: 
276:         if self.cursor.column < left_safe {
277:             // Scroll left: put cursor exactly at left safe boundary
278:             self.viewport.left_column = self.cursor.column.saturating_sub(HORIZONTAL_MARGIN);
279:         } else if self.cursor.column >= right_safe {
280:             // Scroll right: put cursor exactly at right safe boundary
281:             self.viewport.left_column =
282:                 self.cursor.column + HORIZONTAL_MARGIN + 1 - self.viewport.visible_columns;
283:         }
284:     }
285: }
