287: /// Check if a character is a punctuation/symbol boundary (not whitespace)
288: fn is_punctuation(ch: char) -> bool {
289:     matches!(
290:         ch,
291:         '/' | ':'
292:             | ','
293:             | '.'
294:             | '-'
295:             | '('
296:             | ')'
297:             | '{'
298:             | '}'
299:             | '['
300:             | ']'
301:             | ';'
302:             | '"'
303:             | '\''
304:             | '<'
305:             | '>'
306:             | '='
307:             | '+'
308:             | '*'
309:             | '&'
310:             | '|'
311:             | '!'
312:             | '@'
313:             | '#'
314:             | '$'
315:             | '%'
316:             | '^'
317:             | '~'
318:             | '`'
319:             | '\\'
320:             | '?'
321:             | '_'
322:     )
323: }
