325: /// Character type for word navigation (IntelliJ-style)
326: #[derive(Debug, Clone, Copy, PartialEq)]
327: enum CharType {
328:     Whitespace,
329:     WordChar,    // Alphanumeric characters
330:     Punctuation, // Symbols/boundaries
331: }
332: 
333: fn char_type(ch: char) -> CharType {
334:     if ch.is_whitespace() {
335:         CharType::Whitespace
336:     } else if is_punctuation(ch) {
337:         CharType::Punctuation
338:     } else {
339:         CharType::WordChar
340:     }
341: }
342: 
343: /// Check if a character is a word boundary (symbol or whitespace)
344: #[allow(dead_code)]
345: fn is_word_boundary(ch: char) -> bool {
346:     ch.is_whitespace() || is_punctuation(ch)
347: }
