404: fn update(model: &mut Model, msg: Msg) -> Option<Cmd> {
405:     match msg {
406:         Msg::Resize(width, height) => {
407:             model.window_size = (width, height);
408:             model.viewport.visible_lines = (height as usize) / model.line_height;
409:             model.viewport.visible_columns =
410:                 ((width as usize) / model.char_width).saturating_sub(LINE_NUMBER_GUTTER_CHARS);
411:             Some(Cmd::Redraw)
412:         }
413: 
414:         Msg::BlinkCursor => {
415:             let now = Instant::now();
416:             if now.duration_since(model.last_cursor_blink) > Duration::from_millis(500) {
417:                 model.cursor_visible = !model.cursor_visible;
418:                 model.last_cursor_blink = now;
419:                 Some(Cmd::Redraw)
420:             } else {
421:                 None
422:             }
423:         }
424: 
425:         Msg::MoveCursorUp => {
426:             if model.cursor.line > 0 {
427:                 model.cursor.line -= 1;
428: 
429:                 // Maintain desired column for vertical movement
430:                 let desired = model.cursor.desired_column.unwrap_or(model.cursor.column);
431:                 let line_len = model.current_line_length();
432:                 model.cursor.column = desired.min(line_len);
433:                 model.cursor.desired_column = Some(desired);
434: 
435:                 // Scroll only if cursor crosses top boundary (JetBrains-style)
436:                 let padding = model.scroll_padding;
437:                 let top_boundary = model.viewport.top_line + padding;
438: 
439:                 if model.cursor.line < top_boundary && model.viewport.top_line > 0 {
440:                     model.viewport.top_line = model.cursor.line.saturating_sub(padding);
441:                 }
442:             }
443:             model.reset_cursor_blink();
444:             Some(Cmd::Redraw)
445:         }
446: 
447:         Msg::MoveCursorDown => {
448:             if model.cursor.line < model.buffer.len_lines().saturating_sub(1) {
449:                 model.cursor.line += 1;
450: 
451:                 // Maintain desired column for vertical movement
452:                 let desired = model.cursor.desired_column.unwrap_or(model.cursor.column);
453:                 let line_len = model.current_line_length();
454:                 model.cursor.column = desired.min(line_len);
455:                 model.cursor.desired_column = Some(desired);
456: 
457:                 // Scroll only if cursor crosses bottom boundary (JetBrains-style)
458:                 let padding = model.scroll_padding;
459:                 let bottom_boundary =
460:                     model.viewport.top_line + model.viewport.visible_lines - padding - 1;
461:                 let max_top = model
462:                     .buffer
463:                     .len_lines()
464:                     .saturating_sub(model.viewport.visible_lines);
465: 
466:                 if model.cursor.line > bottom_boundary && model.viewport.top_line < max_top {
467:                     let desired_top = model.cursor.line + padding + 1;
468:                     model.viewport.top_line = desired_top
469:                         .saturating_sub(model.viewport.visible_lines)
470:                         .min(max_top);
471:                 }
472:             }
473:             model.reset_cursor_blink();
474:             Some(Cmd::Redraw)
475:         }
476: 
477:         Msg::MoveCursorLeft => {
478:             if model.cursor.column > 0 {
479:                 model.cursor.column -= 1;
480:                 model.cursor.desired_column = None;
481:             } else if model.cursor.line > 0 {
482:                 // Move to end of previous line
483:                 model.cursor.line -= 1;
484:                 model.cursor.column = model.current_line_length();
485:                 model.cursor.desired_column = None;
486:             }
487:             model.ensure_cursor_visible();
488:             model.reset_cursor_blink();
489:             Some(Cmd::Redraw)
490:         }
